CREATE TYPE public.blog_role AS ENUM ('author');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.blog_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own author role" ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_blog_author() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'author'); $$;
REVOKE ALL ON FUNCTION public.is_blog_author() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_blog_author() TO authenticated;
CREATE TABLE public.blog_posts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL DEFAULT auth.uid(), slug text NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'), title text NOT NULL CHECK (length(title) BETWEEN 1 AND 180), excerpt text NOT NULL DEFAULT '', content text NOT NULL DEFAULT '', tags text[] NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK (status IN ('draft','published')), published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK (status <> 'published' OR (published_at IS NOT NULL AND length(trim(content)) > 0)));
GRANT SELECT ON public.blog_posts TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.blog_posts TO authenticated;
GRANT ALL ON public.blog_posts TO service_role;
ALTER TABLE public.blog_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Public published articles" ON public.blog_posts FOR SELECT TO anon, authenticated USING (status = 'published');
CREATE POLICY "Author reads own drafts" ON public.blog_posts FOR SELECT TO authenticated USING (author_id = auth.uid() AND public.is_blog_author());
CREATE POLICY "Author creates own articles" ON public.blog_posts FOR INSERT TO authenticated WITH CHECK (author_id = auth.uid() AND public.is_blog_author());
CREATE POLICY "Author edits own articles" ON public.blog_posts FOR UPDATE TO authenticated USING (author_id = auth.uid() AND public.is_blog_author()) WITH CHECK (author_id = auth.uid() AND public.is_blog_author());
CREATE POLICY "Author deletes own articles" ON public.blog_posts FOR DELETE TO authenticated USING (author_id = auth.uid() AND public.is_blog_author());
CREATE INDEX blog_posts_published_idx ON public.blog_posts(published_at DESC) WHERE status = 'published';
CREATE FUNCTION public.touch_blog_post() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$;
CREATE TRIGGER blog_posts_updated BEFORE UPDATE ON public.blog_posts FOR EACH ROW EXECUTE FUNCTION public.touch_blog_post();